  .brand { min-width: 190px; }
  .resource-pill { min-width: 97px; padding-right: 10px; }
}
@media (max-width: 1160px) {
  body { overflow-y: auto; }
  .app { height: auto; min-height: 100vh; overflow: visible; }
  .game-layout {
    grid-template-columns: 250px minmax(0, 1fr);
