/* Ashen Oath — game systems
   Save-compatible, dependency-free idle RPG state machine. */
(function () {
  'use strict';

  const D = window.GameData;
  const { RARITIES, RARITY_BY_ID, SLOTS, SLOT_BY_ID, PREFIXES, FLAVOR, AFFIXES, UPGRADES, ZONES, CONFIG } = D;
  const SAVE_KEY = 'ashen-oath-save-v1';
  const MAX_LEVEL = 100;

  let state = null;
  let hooks = {};
  let running = false;
  let paused = false;
  let lastFrame = 0;
  let autoTimer = 0;
  let enemyTimer = 0;
  let respawnTimer = 0;
  let vitalsTimer = 0;
  let saveTimer = 0;
  let logEntries = [];
  let offlineSummary = null;
  let lastRegenAt = 0;

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const rand = (a, b) => a + Math.random() * (b - a);
  const randInt = (a, b) => Math.floor(rand(a, b + 1));
  const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
  const round1 = (n) => Math.round(n * 10) / 10;

  function freshZoneProgress() {
    const out = {};
