  position: relative; z-index: 20;
}
.topbar::after {
  content: ""; position: absolute; left: 24px; right: 24px; bottom: -1px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(213, 179, 105, .32), transparent);
}
.brand { display: flex; align-items: center; gap: 11px; min-width: 205px; }
